        private void Filter(){filtering=true;try{layers.Items.Clear();foreach(var r in DrawingSearch.Filter(rows,search.Text,"","",false,false))layers.Items.Add(r.LayerName,checkedLayers.Contains(r.LayerName));}finally{filtering=false;}}
